use std :: collections :: HashMap ; use std :: sync :: Arc ; use std :: time :: Duration ; use chrono :: Local ; use tokio :: sync :: Notify ; use crate :: { ToolCallFull , ToolName , ToolResult } ; use chrono :: { DateTime , Utc } ; use pretty_assertions :: assert_eq ; use super :: * ; impl ChatResponse { # [doc = " Returns `true` if the response contains no meaningful content."] # [doc = ""] # [doc = " A response is considered empty if it's a `TaskMessage` or"] # [doc = " `TaskReasoning` with empty string content. All other variants are"] # [doc = " considered non-empty."] pub fn is_empty (& self) -> bool { match self { ChatResponse :: TaskMessage { content , .. } => match content { ChatResponseContent :: ToolInput (_) => false , ChatResponseContent :: ToolOutput (content) => content . is_empty () , ChatResponseContent :: Markdown { text , .. } => text . is_empty () , } , ChatResponse :: TaskReasoning { content } => content . is_empty () , _ => false , } } }